<?php $page_title='Keranjang';include 'partials/header.php';if($_SERVER['REQUEST_METHOD']==='POST'){foreach($_POST['qty']??[] as $id=>$q){$q=max(0,(int)$q);if($q===0)unset($_SESSION['cart'][$id]);elseif(isset($_SESSION['cart'][$id]))$_SESSION['cart'][$id]['qty']=min($q,$_SESSION['cart'][$id]['stock']);}header('Location: cart.php');exit;}?>
<section class="section container"><div class="section-head"><div><span class="muted">Shopping cart</span><h2>Keranjang Belanja</h2></div></div><?php if(empty($_SESSION['cart'])):?><div class="panel"><p>Keranjang masih kosong.</p><a class="btn" href="products.php">Mulai Belanja</a></div><?php else:?><div class="cart-layout"><form method="post" class="panel"><?php foreach($_SESSION['cart'] as $id=>$i):?><div class="cart-item"><img src="assets/img/<?=htmlspecialchars($i['image'])?>"><div><b><?=htmlspecialchars($i['name'])?></b><p class="muted"><?=rupiah($i['price'])?></p><div class="qty">Qty <input class="input" type="number" min="0" max="<?=$i['stock']?>" name="qty[<?=$id?>]" value="<?=$i['qty']?>"></div></div><b><?=rupiah($i['price']*$i['qty'])?></b></div><?php endforeach;?><button class="btn ghost" style="margin-top:14px">Update Keranjang</button></form><div class="panel" style="height:max-content"><h3>Ringkasan</h3><div class="summary-row"><span>Subtotal</span><b><?=rupiah(cart_total())?></b></div><div class="summary-row"><span>Pengiriman</span><span>Gratis</span></div><div class="summary-row total"><span>Total</span><span><?=rupiah(cart_total())?></span></div><a class="btn" style="width:100%" href="checkout.php">Checkout</a></div></div><?php endif;?></section><?php include 'partials/footer.php';?>
